// Normalize incoming lead data
const input = $input.first().json;
const body = input.body || input;

const lead = {
  lead_id: `lead_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  source: body.source || 'webhook',
  source_content_id: body.content_id || null,
  yacht_id: body.yacht_id || null,
  trigger_keyword: body.keyword || body.trigger_keyword || null,

  name: body.name || '',
  contact: {
    phone: body.phone || body.contact?.phone || '',
    email: body.email || body.contact?.email || '',
    ig_handle: body.ig_handle || body.contact?.ig_handle || '',
    tiktok_handle: body.tiktok_handle || body.contact?.tiktok_handle || ''
  },

  party_details: {
    guests: parseInt(body.guests) || null,
    date: body.date || null,
    duration_hours: parseInt(body.duration) || null,
    occasion: body.occasion || ''
  },

  budget: {
    min: parseFloat(body.budget_min) || null,
    max: parseFloat(body.budget_max) || null,
    currency: 'USD'
  },

  preferences: body.preferences || [],
  notes: body.notes || body.message || '',

  raw_message: body.raw_message || body.message || '',

  status: 'new',
  created_at: new Date().toISOString(),
  updated_at: new Date().toISOString()
};

return [{ json: lead }];

