parameters.jsCode:
// Merge qualification with lead
const lead = $('Normalize Lead Data').first().json;
const qualRaw = $input.first().json;

let qualification = { score: 5, budget_verified: false, date_confirmed: false };
try {
  const parsed = JSON.parse(qualRaw.choices?.[0]?.message?.content || '{}');
  qualification = parsed.qualification || qualification;
} catch (e) {}

// Update lead with qualification
lead.qualification = qualification;
lead.status = qualification.score >= 7 ? 'qualified' : 'new';

// Determine response template based on score
let responseTemplate = 'standard';
if (qualification.score >= 8) responseTemplate = 'hot_lead';
else if (qualification.score <= 3) responseTemplate = 'low_priority';

return [{
  json: {
    lead,
    responseTemplate,
    shouldNotify: qualification.score >= 7
  }
}];

