// Prepare auto-response based on template
const data = $input.first().json;
const template = data.responseTemplate;
const lead = data.lead;

const templates = {
  hot_lead: `Hi ${lead.name || 'there'}! Thanks for your interest in ${lead.yacht_id ? 'the ' + lead.yacht_id : 'our yachts'}. One of our charter specialists will reach out within the hour to help plan your perfect day on the water. In the meantime, feel free to browse our fleet at zenivatravel.com`,

  standard: `Thanks for reaching out! We'd love to help you plan an unforgettable yacht experience in Miami. Could you share: 1) Your preferred date 2) Number of guests 3) Any special occasion? Our team will follow up shortly!`,

  low_priority: `Thanks for your message! Check out our yacht options at zenivatravel.com. For immediate availability, DM us with your preferred date and group size.`
};

return [{
  json: {
    lead_id: lead.lead_id,
    contact: lead.contact,
    response_message: templates[template] || templates.standard,
    template_used: template
  }
}];
